mapper.select:
select a.device_code, a.diagnose_time, min(b.channel_code) as channelCode from vm_device_info_t a join vm_channel_info_t b on a.device_code = b.device_code where a.delete_flag = 0 and b.delete_flag = 0 and a.device_code in
#{deviceCode}
GROUP BY a.device_code

update.foreach:
update vm_device_info_t

        diagnose_result = #{item.diagnoseResult},
        diagnose_time = #{item.diagnoseTime}

where device_code = #{item.deviceCode}
    and IFNULL(diagnose_time, '1970-01-01') < #{item.diagnoseTime}

